{
  "name": "@acme/uikit",
  "version": "0.4.0",
  "description": "ACME internal TypeScript UI component library.",
  "license": "UNLICENSED",
  "main": "src/index.ts",
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "lint": "eslint . --ext .ts",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@typescript-eslint/parser": "6.21.0",
    "eslint": "8.57.0",
    "typescript": "5.4.5"
  },
  "publishConfig": {
    "registry": "http://127.0.0.1:8070/"
  }
}

export { classNames } from "./classNames";
export { formatLabel } from "./label";
// Join truthy class-name parts into a single className string.
export function classNames(
  ...parts: Array<string | false | null | undefined>
): string {
  return parts.filter(Boolean).join(" ");
}
// Format a label with its count.
export function formatLabel(text: string, count: number): string {
  const suffix: string = count.toString();
  return `${text} (${suffix})`;
}

{
  "root": true,
  "parser": "@typescript-eslint/parser",
  "parserOptions": {
    "ecmaVersion": 2020,
    "sourceType": "module"
  },
  "env": {
    "node": true,
    "es2020": true
  },
  "rules": {
    "no-console": "error"
  }
}
